(3631752, 509363, 34938, '<td valign="top">great as a black and white I would have gone for a square crop to remove the number 13 guy out of the image as he is distracting</td>', 'great as a black and white I would have gone for a square crop to remove the number 13 guy out of the image as he is distracting', '2007-05-09 05:19:26.000000', NULL, 1),
(3631753, 507159, 34938, '<td valign="top">just wish you had his feet in this...otherwise a good action shot</td>', 'just wish you had his feet in this...otherwise a good action shot', '2007-05-09 05:20:38.000000', NULL, 1),
(3631754, 508682, 34938, '<td valign="top">I like this...the depth of field is nice, but I think the conversion to duotone might have washed out the exposure a tad. Perhaps a boost in levels would have lifted the contrast to cover for this...</td>', 'I like this...the depth of field is nice, but I think the conversion to duotone might have washed out the exposure a tad. Perhaps a boost in levels would have lifted the contrast to cover for this...', '2007-05-09 05:21:57.000000', NULL, 1),
(3631755, 509286, 34938, '<td valign="top">has to get the blue...congratulations in advance 10...I cannot fault it</td>', 'has to get the blue...congratulations in advance 10...I cannot fault it', '2007-05-09 05:22:24.000000', NULL, 1),
(3631756, 507754, 42181, '<td valign="top">Nice picture with the leading lines of the fence and the runner on the third, IMO shame she wasn''t running in the other direction so the light was on her and not backlighting</td>', 'Nice picture with the leading lines of the fence and the runner on the third, IMO shame she wasn''t running in the other direction so the light was on her and not backlighting', '2007-05-09 05:22:54.000000', NULL, 1),
