(3631896, 507798, 42514, '<td valign="top">Would have loved the photo should she have been in a different pose exposing her face better...</td>', 'Would have loved the photo should she have been in a different pose exposing her face better...', '2007-05-09 07:52:57.000000', NULL, 1),
