(3631905, 507251, 35669, '<td valign="top">funny as hell</td>', 'funny as hell', '2007-05-09 07:59:39.000000', NULL, 1),
(3631909, 509286, 47597, '<td valign="top">Perfect! I love the vibrant red and the frozen action!</td>', 'Perfect! I love the vibrant red and the frozen action!', '2007-05-09 08:01:57.000000', NULL, 1),
(3631911, 509400, 25787, '<td valign="top">A little too good for the brown.</td>', 'A little too good for the brown.', '2007-05-09 08:02:21.000000', NULL, 1),
(3631912, 508704, 47597, '<td valign="top">The sky - which occupies a lot of space - is very stark, and it creates a jarring "cut-out" effect around the man which detracts from the pic for me.</td>', 'The sky - which occupies a lot of space - is very stark, and it creates a jarring "cut-out" effect around the man which detracts from the pic for me.', '2007-05-09 08:03:22.000000', NULL, 1),
(3631916, 509271, 25787, '<td valign="top">Looks too much like a studio shot instead of an action shot.  Otherwise very nice.</td>', 'Looks too much like a studio shot instead of an action shot.  Otherwise very nice.', '2007-05-09 08:04:50.000000', NULL, 1),
(3631936, 506837, 47597, '<td valign="top">Nice capture. I''d prefer it if the kid was more centred.</td>', 'Nice capture. I''d prefer it if the kid was more centred.', '2007-05-09 08:14:03.000000', NULL, 1),
(3631943, 507551, 47597, '<td valign="top">I like the staggered composition. I''d say that the colours are desaturated a bit, wheras I''d prefer them bolder in a sports shot.</td>', 'I like the staggered composition. I''d say that the colours are desaturated a bit, wheras I''d prefer them bolder in a sports shot.', '2007-05-09 08:16:25.000000', NULL, 1),
(3631944, 508622, 25787, '<td valign="top">a little underexposed.  Otherwise interesting shot.</td>', 'a little underexposed.  Otherwise interesting shot.', '2007-05-09 08:17:19.000000', NULL, 1),
(3631945, 507803, 47597, '<td valign="top">You''ve captured a moment here, but I wish I could see the face of one of the subjects - then I''d see some emotion to add weight to the story of the photo.</td>', 'You''ve captured a moment here, but I wish I could see the face of one of the subjects - then I''d see some emotion to add weight to the story of the photo.', '2007-05-09 08:17:30.000000', NULL, 1),
(3631948, 508476, 25787, '<td valign="top">Nice pan.</td>', 'Nice pan.', '2007-05-09 08:18:13.000000', NULL, 1),
(3631949, 507903, 47597, '<td valign="top">I love the grit and speed of the pic. The man''s half-face on the left is a bit distracting, but it''s not a big deal.</td>', 'I love the grit and speed of the pic. The man''s half-face on the left is a bit distracting, but it''s not a big deal.', '2007-05-09 08:18:44.000000', NULL, 1),
(3631955, 509050, 65119, '<td valign="top">Wow, this looks like it has ended up in a serious accident... I hope it didn''t :-)</td>', 'Wow, this looks like it has ended up in a serious accident... I hope it didn''t :-)', '2007-05-09 08:19:41.000000', NULL, 1),
(3631958, 508617, 47597, '<td valign="top">The giant basketball doesn''t add anything to the photo yet it occupies a bit part of the frame. It would be better if the girl was looking at the camera, or was otherwise showing some kind of emotion. The bright reflection of the sun on her arms is a bit distracting.</td>', 'The giant basketball doesn''t add anything to the photo yet it occupies a bit part of the frame. It would be better if the girl was looking at the camera, or was otherwise showing some kind of emotion. The bright reflection of the sun on her arms is a bit distracting.', '2007-05-09 08:20:40.000000', NULL, 1),
(3631963, 509400, 44825, '<td valign="top">VERY pixelated and not in focus</td>', 'VERY pixelated and not in focus', '2007-05-09 08:21:44.000000', NULL, 1),
(3631964, 507180, 65119, '<td valign="top">I like the composition here but the clarity.... Subject must be clear and sharp mate... :-)</td>', 'I like the composition here but the clarity.... Subject must be clear and sharp mate... :-)', '2007-05-09 08:21:47.000000', NULL, 1),
(3631965, 508880, 47597, '<td valign="top">Classic shot. A pity that I cannot see any of the subjects faces - then I''d get to see some emotion. I like the good crisp focus.</td>', 'Classic shot. A pity that I cannot see any of the subjects faces - then I''d get to see some emotion. I like the good crisp focus.', '2007-05-09 08:21:53.000000', NULL, 1),
(3631967, 507758, 47597, '<td valign="top">Interesting pose! In this frozen-action style photo I''d prefer if the ball and feet were in crisp focus.</td>', 'Interesting pose! In this frozen-action style photo I''d prefer if the ball and feet were in crisp focus.', '2007-05-09 08:23:09.000000', NULL, 1),
(3631971, 509147, 47597, '<td valign="top">I can see the scene, but wish I could see more detail of the action. It''s all a bit too distant to keep my interest.</td>', 'I can see the scene, but wish I could see more detail of the action. It''s all a bit too distant to keep my interest.', '2007-05-09 08:24:42.000000', NULL, 1),
(3631972, 509318, 47597, '<td valign="top">I like this shot. It is unusual amidst the other full colour pics and I like the action that has been captured.</td>', 'I like this shot. It is unusual amidst the other full colour pics and I like the action that has been captured.', '2007-05-09 08:25:51.000000', NULL, 1),
(3631978, 509363, 36006, '<td valign="top">Comp ok, light ok,  made the rule of 6 for sports, emotional factor could be more heightened by seeing the runner or the catchers face, good stop action, nice movement, great lines, tonal value just on the edge, the whites are barely in, the blacks seem a bit deep, texture needs work, overall a good attempt</td>', 'Comp ok, light ok,  made the rule of 6 for sports, emotional factor could be more heightened by seeing the runner or the catchers face, good stop action, nice movement, great lines, tonal value just on the edge, the whites are barely in, the blacks seem a bit deep, texture needs work, overall a good attempt', '2007-05-09 08:28:14.000000', NULL, 1),
(3631981, 508845, 47597, '<td valign="top">What an exciting moment! I like the fact that I can see the emotion in the face of the player, but the colours are quite dull. I would think that adjusting the levels could improve this. The fence is also a distraction.</td>', 'What an exciting moment! I like the fact that I can see the emotion in the face of the player, but the colours are quite dull. I would think that adjusting the levels could improve this. The fence is also a distraction.', '2007-05-09 08:28:35.000000', NULL, 1),
(3631985, 509271, 65119, '<td valign="top">I love this pic... But if I were behind the lens I would have tried it out with 1 light source on the right hand side of the subject and left the left hand side in total... or almost... darkness... Try it out when you have a min... I believe you''ll have a better result although I like this one very much...</td>', 'I love this pic... But if I were behind the lens I would have tried it out with 1 light source on the right hand side of the subject and left the left hand side in total... or almost... darkness... Try it out when you have a min... I believe you''ll have a better result although I like this one very much...', '2007-05-09 08:29:44.000000', NULL, 1),
(3631988, 509389, 36006, '<td valign="top">the face has way more of an emotional value than the back side. In sports, this is a crucial element.</td>', 'the face has way more of an emotional value than the back side. In sports, this is a crucial element.', '2007-05-09 08:30:50.000000', NULL, 1),
(3631991, 507949, 47597, '<td valign="top">Great action moment, but I wish I could see the faces of the actors - then I could see some emotion. I think sepia was a good choice.</td>', 'Great action moment, but I wish I could see the faces of the actors - then I could see some emotion. I think sepia was a good choice.', '2007-05-09 08:31:19.000000', NULL, 1),
(3631995, 507657, 47597, '<td valign="top">The subjects of the photo are too far away to appreciate fully. There''s not enough interest in the photo to keep my attention for long.</td>', 'The subjects of the photo are too far away to appreciate fully. There''s not enough interest in the photo to keep my attention for long.', '2007-05-09 08:32:29.000000', NULL, 1),
(3631997, 507696, 47597, '<td valign="top">Wonderful frozen moment! I''m not sure if I would have preferred a tighter crop on the left, but I can see that you''ve kept the pole center.</td>', 'Wonderful frozen moment! I''m not sure if I would have preferred a tighter crop on the left, but I can see that you''ve kept the pole center.', '2007-05-09 08:33:57.000000', NULL, 1),
(3631998, 508950, 29748, '<td valign="top">Very nice and clear, but distant.</td>', 'Very nice and clear, but distant.', '2007-05-09 08:34:19.000000', NULL, 1),
(3632000, 507240, 29748, '<td valign="top">Very bright and clear, nice angle</td>', 'Very bright and clear, nice angle', '2007-05-09 08:34:43.000000', NULL, 1),
(3632001, 507156, 29748, '<td valign="top">intersting</td>', 'intersting', '2007-05-09 08:35:02.000000', NULL, 1),
(3632002, 508498, 47597, '<td valign="top">Vibrant colours are great. I like the fact that I can see the actors faces and their emotions. I''d give it a 10 if the ball was in crisp focus.</td>', 'Vibrant colours are great. I like the fact that I can see the actors faces and their emotions. I''d give it a 10 if the ball was in crisp focus.', '2007-05-09 08:35:06.000000', NULL, 1),
(3632004, 509110, 29748, '<td valign="top">Im sorry but this is not interesting to me.</td>', 'Im sorry but this is not interesting to me.', '2007-05-09 08:35:52.000000', NULL, 1),
(3632005, 508403, 29748, '<td valign="top">Was it a strike?</td>', 'Was it a strike?', '2007-05-09 08:36:02.000000', NULL, 1),
(3632006, 509432, 36006, '<td valign="top">The comp is good, but a tighter crop is what is needed. The left of the pitcher. color great, fence line chopping through pitcher undesirable, light flat but expected for this type of sport, great capture, nice movement, excellent emotional value, nice texture, blacks seem just a bit deep, whites are just ok, overall a great attempt</td>', 'The comp is good, but a tighter crop is what is needed. The left of the pitcher. color great, fence line chopping through pitcher undesirable, light flat but expected for this type of sport, great capture, nice movement, excellent emotional value, nice texture, blacks seem just a bit deep, whites are just ok, overall a great attempt', '2007-05-09 08:36:17.000000', NULL, 1),
(3632007, 508563, 47597, '<td valign="top">I don''t get the point of the partial desaturation because it draws focus onto the grass instead of onto the players. I''d prefer if I can see the faces and emotions of the players.</td>', 'I don''t get the point of the partial desaturation because it draws focus onto the grass instead of onto the players. I''d prefer if I can see the faces and emotions of the players.', '2007-05-09 08:36:18.000000', NULL, 1),
(3632008, 509497, 29748, '<td valign="top">Great stop action.  Colors are bright and vibrant.  Clear and crisp</td>', 'Great stop action.  Colors are bright and vibrant.  Clear and crisp', '2007-05-09 08:36:30.000000', NULL, 1),
(3632013, 507913, 47597, '<td valign="top">The slight tilt puts me off, but it''s a good moment captured.</td>', 'The slight tilt puts me off, but it''s a good moment captured.', '2007-05-09 08:39:55.000000', NULL, 1),
(3632016, 509084, 61073, '<td valign="top">Love it..</td>', 'Love it..', '2007-05-09 08:40:42.000000', NULL, 1),
(3632017, 509164, 44825, '<td valign="top">!!!!!</td>', '!!!!!', '2007-05-09 08:40:48.000000', NULL, 1),
(3632020, 509254, 47597, '<td valign="top">I like the emotion in the pic.</td>', 'I like the emotion in the pic.', '2007-05-09 08:41:41.000000', NULL, 1),
(3632023, 507100, 47597, '<td valign="top">The action is a little too distant to keep me interested. I''d prefer if the chaser was more in the picture.</td>', 'The action is a little too distant to keep me interested. I''d prefer if the chaser was more in the picture.', '2007-05-09 08:42:27.000000', NULL, 1),
(3632027, 509400, 51793, '<td valign="top">ouch, looks very blown up and hard to see the subject. Looks like you need a better phone camera. lighting needs to be stonger and try useing a macro if you have the ability.</td>', 'ouch, looks very blown up and hard to see the subject. Looks like you need a better phone camera. lighting needs to be stonger and try useing a macro if you have the ability.', '2007-05-09 08:43:32.000000', NULL, 1),
(3632033, 507180, 47597, '<td valign="top">Skiing is a good opportunity for action shots because you''re shooting from an angle that allows me to see the face and emotion of the skier. A pity about the blur. I would also have looked at maybe keeping the attention on the person by placing him in the centre of the pic and with a tighter zoom.</td>', 'Skiing is a good opportunity for action shots because you''re shooting from an angle that allows me to see the face and emotion of the skier. A pity about the blur. I would also have looked at maybe keeping the attention on the person by placing him in the centre of the pic and with a tighter zoom.', '2007-05-09 08:45:05.000000', NULL, 1),
(3632039, 509164, 51638, '<td valign="top">I''m afraid this is just a little too creative for me. Sorry.</td>', 'I''m afraid this is just a little too creative for me. Sorry.', '2007-05-09 08:45:56.000000', NULL, 1),
(3632043, 509169, 51638, '<td valign="top">Lighting is a little too harsh IMO.</td>', 'Lighting is a little too harsh IMO.', '2007-05-09 08:46:51.000000', NULL, 1),
