(3632558, 509164, 34481, '<td valign="top">Why?</td>', 'Why?', '2007-05-09 10:54:03.000000', NULL, 1),
(3632560, 508549, 77364, '<td valign="top">Awesome!  You were able to capture the essense of this challenge perfectly.  I love the color of the water and how the orange sail jumps out at you.  I would have considered cropping more of the bottom, but that is just me.  Great job</td>', 'Awesome!  You were able to capture the essense of this challenge perfectly.  I love the color of the water and how the orange sail jumps out at you.  I would have considered cropping more of the bottom, but that is just me.  Great job', '2007-05-09 10:54:21.000000', NULL, 1),
(3632563, 508708, 77364, '<td valign="top">Interesting.  The colors are amazing, but you really have to look to see the person on the bike.  Good try though</td>', 'Interesting.  The colors are amazing, but you really have to look to see the person on the bike.  Good try though', '2007-05-09 10:55:09.000000', NULL, 1),
(3632566, 509163, 54446, '<td valign="top">Great job!  Wonderful exposure on the face.  If you used a fill flash, there is no evidence of it, other than a great looking image.  The background is perfectly blurred, throwing the attention to the athlete.  (10)</td>', 'Great job!  Wonderful exposure on the face.  If you used a fill flash, there is no evidence of it, other than a great looking image.  The background is perfectly blurred, throwing the attention to the athlete.  (10)', '2007-05-09 10:55:58.000000', NULL, 1),
