(3632573, 507341, 77364, '<td valign="top">Fantastic!  I would have considered cropping more of the right side.  Great entry - nice job!</td>', 'Fantastic!  I would have considered cropping more of the right side.  Great entry - nice job!', '2007-05-09 10:56:57.000000', NULL, 1),
(3632579, 507696, 54446, '<td valign="top">Great timing.  Beautiful, elegant, stunning, interesting.... I could go on.  Clearly my favorite in this challenge and the one I hope gets a blue ribbon.  (10)</td>', 'Great timing.  Beautiful, elegant, stunning, interesting.... I could go on.  Clearly my favorite in this challenge and the one I hope gets a blue ribbon.  (10)', '2007-05-09 10:57:33.000000', NULL, 1),
