(3634603, 508191, 42256, '<td valign="top">Really like the concept and composition! tad underexposed though! 6</td>', 'Really like the concept and composition! tad underexposed though! 6', '2007-05-09 18:55:56.000000', NULL, 1),
(3634611, 508584, 42256, '<td valign="top">love how you have stopped the moment.  I don''t like that black rod (??) thing in front of the kid. Also a little noisy!</td>', 'love how you have stopped the moment.  I don''t like that black rod (??) thing in front of the kid. Also a little noisy!', '2007-05-09 18:57:40.000000', NULL, 1),
(3634613, 508211, 42256, '<td valign="top">amazing colors, while i love how everything is sharp, this sharpness is driving my eyes from the kids to the sand in the foreground.  Still a nice capture and control of light! 7</td>', 'amazing colors, while i love how everything is sharp, this sharpness is driving my eyes from the kids to the sand in the foreground.  Still a nice capture and control of light! 7', '2007-05-09 18:58:41.000000', NULL, 1),
