(3635548, 508950, 75034, '<td valign="top">If we were able to rate a zero.  Then this photo would receive one.  Not for the photo itself, because I like the composition and the color of the contrast but for the simple fact that Barry Bonds, in my opinion as well as many other people''s opinions is a cheat and is stealing a record away from someone who genuinely worked hard at the games for the love of the game.  If Bonds could have achieved such success in the same manner as those before him without cheating than my hat would go off to him but because he continues to climb ever closer to a record that was achieved by a remarkable human being, by way of cheating.  He earns absolutely no respect or admiration from me.</td>', 'If we were able to rate a zero.  Then this photo would receive one.  Not for the photo itself, because I like the composition and the color of the contrast but for the simple fact that Barry Bonds, in my opinion as well as many other people''s opinions is a cheat and is stealing a record away from someone who genuinely worked hard at the games for the love of the game.  If Bonds could have achieved such success in the same manner as those before him without cheating than my hat would go off to him but because he continues to climb ever closer to a record that was achieved by a remarkable human being, by way of cheating.  He earns absolutely no respect or admiration from me.', '2007-05-10 00:12:20.000000', NULL, 1),
(3635563, 509107, 15407, '<td valign="top">I love this image; am curious how you achieved the white background.</td>', 'I love this image; am curious how you achieved the white background.', '2007-05-10 00:18:52.000000', NULL, 1),
(3635571, 507847, 54431, '<td valign="top">Love it! Awesome shot. Perfect silhouette, great composition, and the colors of the sky are beautiful!</td>', 'Love it! Awesome shot. Perfect silhouette, great composition, and the colors of the sky are beautiful!', '2007-05-10 00:21:11.000000', NULL, 1),
(3635584, 507803, 75034, '<td valign="top">It''s a shame that such a wonderful piece of baseball history can be won over someone who has to cheat to achieve the goal of someone who just played for the love the game.</td>', 'It''s a shame that such a wonderful piece of baseball history can be won over someone who has to cheat to achieve the goal of someone who just played for the love the game.', '2007-05-10 00:25:39.000000', NULL, 1),
