(3645307, 508088, 66494, '<td valign="top">love the tongue action, the colors, the clarity, the diagonal (really adds excitement), all lead to a very well done shot. NICE</td>', 'love the tongue action, the colors, the clarity, the diagonal (really adds excitement), all lead to a very well done shot. NICE', '2007-05-14 00:33:08.000000', NULL, 1),
(3645319, 507251, 66494, '<td valign="top">Nice fun action shot</td>', 'Nice fun action shot', '2007-05-14 00:35:59.000000', NULL, 1),
