(3645327, 508080, 66494, '<td valign="top">neat title</td>', 'neat title', '2007-05-14 00:37:30.000000', NULL, 1),
(3645567, 509025, 77724, '<td valign="top">Very powerful.  You really capture the emotion by framing his face with the front runners and draw attention with shallow DoF on subject. And the #1 bib shows - nice catch on that.  Excellent.</td>', 'Very powerful.  You really capture the emotion by framing his face with the front runners and draw attention with shallow DoF on subject. And the #1 bib shows - nice catch on that.  Excellent.', '2007-05-14 01:15:01.000000', NULL, 1),
