(3645963, 508414, 20956, '<td valign="top">Excellent shot at catching that precise moment.</td>', 'Excellent shot at catching that precise moment.', '2007-05-14 02:47:24.000000', NULL, 1),
(3645967, 509169, 20956, '<td valign="top">Your light is too harsh causing some extreme shadows.</td>', 'Your light is too harsh causing some extreme shadows.', '2007-05-14 02:48:22.000000', NULL, 1),
