(3646140, 508676, 20956, '<td valign="top">Very good composition. I don''t care for the black and white or sepia conversion. It just looks off. Color would have been better.</td>', 'Very good composition. I don''t care for the black and white or sepia conversion. It just looks off. Color would have been better.', '2007-05-14 03:53:11.000000', NULL, 1),
(3646147, 508088, 20956, '<td valign="top">Very good focus (both the batter and photographer), nice crop.</td>', 'Very good focus (both the batter and photographer), nice crop.', '2007-05-14 03:55:48.000000', NULL, 1),
(3646148, 507847, 20956, '<td valign="top">One of the best silhouette in the contest.</td>', 'One of the best silhouette in the contest.', '2007-05-14 03:56:39.000000', NULL, 1),
(3646150, 509254, 20956, '<td valign="top">Nice composition but the color is over saturated.</td>', 'Nice composition but the color is over saturated.', '2007-05-14 03:57:21.000000', NULL, 1),
(3646154, 509432, 20956, '<td valign="top">It would have been better if the photo had been cropped to include the pitcher only, thus eliminating the busy background.</td>', 'It would have been better if the photo had been cropped to include the pitcher only, thus eliminating the busy background.', '2007-05-14 03:58:54.000000', NULL, 1),
(3646156, 508539, 20956, '<td valign="top">Slightly out of focus.</td>', 'Slightly out of focus.', '2007-05-14 03:59:20.000000', NULL, 1),
(3646157, 509225, 20956, '<td valign="top">Nice action shot with good focus.</td>', 'Nice action shot with good focus.', '2007-05-14 03:59:52.000000', NULL, 1),
(3646159, 508063, 20956, '<td valign="top">Out of focus</td>', 'Out of focus', '2007-05-14 04:00:29.000000', NULL, 1),
(3646163, 507406, 20956, '<td valign="top">Cropping would have helped this photo. The background is way to busy. Maybe only include the front 2 men and the four nearest balls.</td>', 'Cropping would have helped this photo. The background is way to busy. Maybe only include the front 2 men and the four nearest balls.', '2007-05-14 04:03:51.000000', NULL, 1),
(3646165, 509338, 20956, '<td valign="top">No main point of interest.</td>', 'No main point of interest.', '2007-05-14 04:04:32.000000', NULL, 1),
(3646186, 509163, 20956, '<td valign="top">A vertical crop would have brought this photo up to a 9 or 10. The background is way to busy. Nice photo.</td>', 'A vertical crop would have brought this photo up to a 9 or 10. The background is way to busy. Nice photo.', '2007-05-14 04:19:25.000000', NULL, 1),
(3646189, 508561, 20956, '<td valign="top">Very good photo. The ball is a little overexposed.</td>', 'Very good photo. The ball is a little overexposed.', '2007-05-14 04:20:21.000000', NULL, 1),
(3646192, 507650, 20956, '<td valign="top">There is something weird about the color, almost a red hue to it. Focus could be a little sharper.</td>', 'There is something weird about the color, almost a red hue to it. Focus could be a little sharper.', '2007-05-14 04:22:06.000000', NULL, 1),
(3646253, 509286, 60195, '<td valign="top">Terrific shot in all aspects.  This just screems "speed". Remarkable clarity/sharpness combined with wheel/brake blur. I''m sure you could shoot BSB for a living (if you don''t already). Worthy of a cover, and my pick for the Blue. Good luck! 9</td>', 'Terrific shot in all aspects.  This just screems "speed". Remarkable clarity/sharpness combined with wheel/brake blur. I''m sure you could shoot BSB for a living (if you don''t already). Worthy of a cover, and my pick for the Blue. Good luck! 9', '2007-05-14 05:10:57.000000', NULL, 1),
(3646254, 508032, 60195, '<td valign="top">Awesome shot.  Should definitely be on the front page. Good luck!</td>', 'Awesome shot.  Should definitely be on the front page. Good luck!', '2007-05-14 05:11:08.000000', NULL, 1),
(3646589, 509499, 46314, '<td valign="top">Nice action shot. There''s a lot going on in the shot, and the laces are humourous, so it really draws the viewer in. There is a bit of distraction in the background though, but I guess that just gives it a setting...</td>', 'Nice action shot. There''s a lot going on in the shot, and the laces are humourous, so it really draws the viewer in. There is a bit of distraction in the background though, but I guess that just gives it a setting...', '2007-05-14 09:04:39.000000', NULL, 1),
