(3646620, 509144, 46314, '<td valign="top">Nice action. I like the bold colours.</td>', 'Nice action. I like the bold colours.', '2007-05-14 09:12:20.000000', NULL, 1),
(3646624, 509084, 46314, '<td valign="top">Great action shot of the dog. The composition could be strengthened a little, and the runner is a bit distracting - maybe he could be cropped off.</td>', 'Great action shot of the dog. The composition could be strengthened a little, and the runner is a bit distracting - maybe he could be cropped off.', '2007-05-14 09:13:12.000000', NULL, 1),
(3646629, 509444, 46314, '<td valign="top">Nicely timed shot, and good composition.</td>', 'Nicely timed shot, and good composition.', '2007-05-14 09:14:08.000000', NULL, 1),
